    public static void main(String[] args) throws Exception {
        Constructor<?> 产房 = Cat.class.getDeclaredConstructor(String.class);
        Cat 猫 = (Cat) 产房.newInstance("{v}");
        System.out.println("接生出来这只叫：" + 猫.{f});
